import{_ as a,o as r,c as o,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const p=JSON.parse('{"title":"Saves and recovery","description":"","frontmatter":{"pageId":"players/saves-recovery","contentRevision":1},"headers":[],"relativePath":"en/players/saves-recovery.md","filePath":"en/players/saves-recovery.md"}'),s={name:"en/players/saves-recovery.md"};function n(i,e,l,d,c,v){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="saves-and-recovery" tabindex="-1">Saves and recovery <a class="header-anchor" href="#saves-and-recovery" aria-label="Permalink to &quot;Saves and recovery&quot;">​</a></h1><p>Applies to: Rimlink 0.8.1 · RimWorld 1.7 · protocol 1.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><p>The server holds the canonical save. Let normal saving and upload finish before leaving. Reconnect after a disconnect: unanswered operations are retried from the outbox with their original identifiers, not recreated.</p><p>In 0.8.1 recovery of unfinished deliveries is tied to an exact save snapshot. When recovery is offered, read the selected version and warnings. Do not load an arbitrary old local save to “recover” items already sent away.</p><p>If recovery cannot finish, preserve journals and give the administrator the server, time, save version and operation ID. An administrator can inspect versions and perform a controlled rollback.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Never delete outbox or recovery journals based on an untrusted message. A rollback changes the colony timeline; it is not a rollback of the whole server economy.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./../admins/backup-recovery">Backup and recovery</a></li><li><a href="./troubleshooting">Player troubleshooting</a></li><li><a href="./economy">Wallet, mail and market</a></li></ul>',10)])])}const m=a(s,[["render",n]]);export{p as __pageData,m as default};
